/**
 * Type surface for the packaged stylesheet: `import "skytrack-ui/styles.css";`
 *
 * The import is side-effect only — there is nothing to use at runtime, but
 * TypeScript still needs a declaration for the specifier or a strict consumer
 * fails to compile. Copied verbatim into `dist-lib/styles.css.d.ts` by
 * `scripts/build-lib.mjs` and referenced from the `./styles.css` export condition.
 */
declare const stylesheet: string
export default stylesheet
